    "D1": {
      "design": "Review",
      "population": "Patients and lay press",
      "intervention_comparator": "Coffee consumption vs. no coffee consumption",
      "outcomes": "Gastro-oesophageal reflux, dyspepsia, gastrin release, gastric acid secretion, lower oesophageal sphincter pressure, gastric emptying, small bowel transit, cholecystokinin release, gallbladder contraction, rectosigmoid motor activity",
      "results": "Coffee promotes gastro-oesophageal reflux; no association between coffee and dyspepsia; coffee stimulates gastrin release and gastric acid secretion; conflicting results on lower oesophageal sphincter pressure; coffee may slow gastric emptying but other studies indicate no effect on gastric emptying or small bowel transit; coffee induces cholecystokinin release and gallbladder contraction; coffee increases rectosigmoid motor activity within 4 min after ingestion",
      "limitations": "No specific population or intervention details provided; review of literature without experimental data",
      "quote_ids": ["D1-Q1", "D1-Q2", "D1-Q3"]
    },
    "D2": {
      "design": "Randomized controlled trial",
      "population": "10 young asymptomatic habitual coffee drinkers",
      "intervention_comparator": "Coffee consumption vs. 48-hour coffee abstinence",
      "outcomes": "Sucrose permeability",
      "results": "Habitual coffee drinkers had significantly higher sucrose excretion (p < 0.01) compared to non-coffee drinkers; after 48-hour coffee abstinence, sucrose excretion decreased significantly (p < 0.05) to levels not differing from non-coffee drinkers",
      "limitations": "Small sample size (n=10); short abstinence period (48 hours); no control group for coffee abstinence",
      "quote_ids": ["D2-Q4", "D2-Q5", "D2-Q8"]
    }
  },
  "criteria": [
    {
      "wording": "Avoid drinking coffee on an empty stomach to prevent acidity",
      "role": "core",
      "conclusion": "insufficient_evidence",
      "applicability": "indirect",
      "evidence_strength": "limited",
      "rationale": "D1 shows coffee promotes gastro-oesophageal reflux but no association with dyspepsia; D2 shows coffee may damage gastroduodenal mucosa but does not directly address acidity prevention. Neither study provides evidence that avoiding coffee on empty stomach prevents acidity. The claim implies a causal relationship that is not supported by the data. Coffee's effects on acidity are not directly measured in the studies, and the claim's recommendation is not tested in the studies.",
